import React from "react";

const ageGroups = [
  {
    id: "2-5",
    title: "Little Explorers",
    age: "Ages 2–5",
    color: "from-purple-200 to-purple-300",
    image: "/assets/images/games/bear.png",
    link: "https://www.pbskids.org/games/", // пример внешнего сайта для малышей
    items: ["Memory", "Matching shapes", "Tap the animal", "Sounds & emotions"],
  },
  {
    id: "6-8",
    title: "Play & Learn",
    age: "Ages 6–8",
    color: "from-blue-200 to-blue-300",
    image: "/assets/images/games/con.png",
    link: "https://www.funbrain.com/games", // пример внешнего сайта для детей
    items: ["Quizzes", "Math games", "Word puzzles", "Hospital games"],
  },
  {
    id: "9-12",
    title: "Smart Games",
    age: "Ages 9–12",
    color: "from-green-200 to-green-300",
    image: "/assets/images/games/smart-games.png",
    link: "https://www.coolmathgames.com/", // пример внешнего сайта
    items: ["Logic puzzles", "Timed quizzes", "Adventure learning", "Help the doctor"],
  },
  {
    id: "13-18",
    title: "Challenge Zone",
    age: "Ages 13–18",
    color: "from-violet-400 to-violet-500",
    image: "/assets/images/games/brain.png",
    link: "https://www.brainist.com/games", // пример внешнего сайта для подростков
    items: ["Brain games", "Strategy games", "Quizzes", "Relax games"],
  },
];

export default function Games() {
  return (
    <div className="p-8">
      <h1 className="text-4xl font-bold mb-2 flex items-center gap-2">🎮 Games</h1>
      <p className="text-gray-500 mb-8">Choose your age group and start playing!</p>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        {ageGroups.map((group) => (
          <div
            key={group.id}
            className={`rounded-3xl p-4 text-center shadow-lg bg-gradient-to-b ${group.color} flex flex-col items-center transition hover:scale-105`}
          >
            {/* Картинка сверху */}
            <img
              src={group.image}
              alt={group.title}
              className="w-32 h-32 object-contain mb-4 rounded-full border-4 border-white shadow-md"
            />

            <h2 className="text-sm text-gray-700 mb-1">{group.age}</h2>
            <h3 className="text-xl font-bold mb-3">{group.title}</h3>

            <ul className="text-sm text-gray-700 mb-4 space-y-1">
              {group.items.map((item) => (
                <li key={item}>• {item}</li>
              ))}
            </ul>

            <a href={group.link} target="_blank" rel="noopener noreferrer">
              <button className="bg-green-500 hover:bg-green-600 text-white px-6 py-2 rounded-full font-semibold transition">
                Play Games
              </button>
            </a>
          </div>
        ))}
      </div>
    </div>
  );
}
